KG42.register("rules-29a3a6eda4166e02b7c17c66",{"id":"48-multiple_energy_carrier_market::v141-c-R005","paper":"48-multiple_energy_carrier_market","record":{"rule_id":"v141-c-R005","mechanism_id":"v141-a-M01","name":"Local market coordinator","process_stage":"coordination","market_meaning":"Demand bids are submitted to the central market operator at a specific time and in accordance with a standardized bid format. Scope: Scheduled bid submission in the centralized two-sided local auction. Supply bids are submitted to the central market operator at a specific time and in accordance with a standardized bid format. Scope: Scheduled bid submission in the centralized two-sided local auction. The market operator is responsible for continuous operation of the local market and its supporting functions. Scope: Continuous operation of the local market and its supporting functions. The market operator should preferably be financially independent from the owners of market participants. Scope: Financial relationship between the market operator and market-participant owners. The market operator informs each agent whether or not its bids cleared. Scope: Communication of bid-clearing outcomes to agents in the local auction.","independence_rationale":"Relations governed by the approved function coordination.local_operator under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand","bidding.supply","coordination.local_operator"],"E":[{"edge_id":"v141-c-R005-E001","source":"bidding.demand","target":"coordination.local_operator","type":"links","constraint_ids":["v141-c-R005-C001"],"evidence_ids":["v141-b-g01-E007","v141-b-g01-E015"]},{"edge_id":"v141-c-R005-E002","source":"bidding.supply","target":"coordination.local_operator","type":"links","constraint_ids":["v141-c-R005-C002"],"evidence_ids":["v141-b-g01-E007","v141-b-g01-E015"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Communication of bid-clearing outcomes to agents in the local auction. | Continuous operation of the local market and its supporting functions. | Financial relationship between the market operator and market-participant owners. | Scheduled bid submission in the centralized two-sided local auction.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E006","v141-b-g01-E007","v141-b-g01-E015"]},"x":[],"theta":[],"phi":[{"constraint_id":"v141-c-R005-C001","kind":"procedural","role":"core","statement":"Demand bids are submitted to the central market operator at a specific time and in accordance with a standardized bid format. Scope: Scheduled bid submission in the centralized two-sided local auction.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand","coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E007","v141-b-g01-E015"]},{"constraint_id":"v141-c-R005-C002","kind":"procedural","role":"core","statement":"Supply bids are submitted to the central market operator at a specific time and in accordance with a standardized bid format. Scope: Scheduled bid submission in the centralized two-sided local auction.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.supply","coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E007","v141-b-g01-E015"]},{"constraint_id":"v141-c-R005-C003","kind":"procedural","role":"core","statement":"The market operator is responsible for continuous operation of the local market and its supporting functions. Scope: Continuous operation of the local market and its supporting functions.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E006"]},{"constraint_id":"v141-c-R005-C004","kind":"procedural","role":"core","statement":"The market operator should preferably be financially independent from the owners of market participants. Scope: Financial relationship between the market operator and market-participant owners.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E006"]},{"constraint_id":"v141-c-R005-C005","kind":"procedural","role":"core","statement":"The market operator informs each agent whether or not its bids cleared. Scope: Communication of bid-clearing outcomes to agents in the local auction.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E007"]}],"pi":[{"evidence_id":"v141-b-g01-E006","location":{"location_id":"src-ec182c21f1-p03-c1r4__v141-a-M01-participation","page":3,"printed_page":null,"section":null,"anchor_text":"the local market and other surrounding energy systems. A retailer uptherefore does not represent a p","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"The local market clearing function is matching the submitted supply and demand bids, taking into account aspects such as grid constraints. The clearing function is operated by a market operator, which is responsible for the continuous operation of the local market and its supporting functions, and should therefore preferably be financially independent from the owners of the market participants."},{"evidence_id":"v141-b-g01-E007","location":{"location_id":"src-ec182c21f1-p03-c2r1__v141-a-M01-bidding","page":3,"printed_page":null,"section":null,"anchor_text":"Electrical Power and Energy Systems 118 (2020) 105739 of 4.1. Main ingredients s- se 4.1.1. Centrali","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Like many wholesale electricity markets, the proposed market is based on a centralized two-sided auction format. It is a centralized auction in the sense that all agents submit bids to a central market operator, at a specific time and in accordance with a standardized bid format. Once all bids have been received, the market operator clears the market, meaning that it identifies which bids should be accepted, based on the information contained in the bids. The market operator informs each agent whether or not their bids cleared."},{"evidence_id":"v141-b-g01-E015","location":{"location_id":"src-ec182c21f1-p04-c1r2__v141-a-M01-bidding","page":4,"printed_page":null,"section":null,"anchor_text":"energy will be injected or withdrawn). In addition, each bid states a 4. single quantity (in kWh) an","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"In the proposed market design, each individual bid has a very simple structure. Each bid contains basic information about what the bid is for (i.e. it specifies an energy carrier, a delivery-hour, whether it is a supply or demand bid, and the location on the network where the energy will be injected or withdrawn). In addition, each bid states a single quantity (in kWh) and a single valuation (in €/kWh)."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":"No design-selection or operational decision variable is declared for this coordination rule. C001-C005 describe bid-intake timing and format, continuous operation, an organizational independence preference, and clearing notification; the source scope provides no quantitative decision variable to formalize.","empty_theta_reason":"No fixed quantitative parameter or value is declared for this coordination rule. The source does not specify a submission deadline, bid-format coefficient, ownership parameter, notification variable, or other numerical constant within C001-C005, so no parameter can be supplied without inventing one."},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-participation"],"extras":{"decision_anchor":"coordination.local_operator","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E007","quote":"It is a centralized auction in the sense that all agents submit bids to a central market operator, at a specific time and in accordance with a standardized bid format."},{"evidence_id":"v141-b-g01-E015","quote":"Each bid contains basic information about what the bid is for (i.e. it specifies an energy carrier, a delivery-hour, whether it is a supply or demand bid, and the location on the network where the energy will be injected or withdrawn)."}],[{"evidence_id":"v141-b-g01-E007","quote":"It is a centralized auction in the sense that all agents submit bids to a central market operator, at a specific time and in accordance with a standardized bid format."},{"evidence_id":"v141-b-g01-E015","quote":"Each bid contains basic information about what the bid is for (i.e. it specifies an energy carrier, a delivery-hour, whether it is a supply or demand bid, and the location on the network where the energy will be injected or withdrawn)."}],[{"evidence_id":"v141-b-g01-E006","quote":"a market operator, which is responsible for the continuous operation of the local market and its supporting functions"}],[{"evidence_id":"v141-b-g01-E006","quote":"a market operator, which is responsible for the continuous operation of the local market and its supporting functions, and should therefore preferably be financially independent from the owners of the market participants."}],[{"evidence_id":"v141-b-g01-E007","quote":"The market operator informs each agent whether or not their bids cleared."}]],"C2_formalization":{"graph_sha256":"7fdfa4cb939179d25df62669a0ea37eddd42bd385e904ad9093e29217a5371bb","applicability":"non_mathematical","reason":"The rule governs institutional coordination rather than a quantitative market mechanism: standardized bid receipt by a central market operator, continuous operation of the local market, a preference for operator financial independence, and notification of clearing outcomes. The supplied source passages state obligations, preferences, and communication procedures; within this rule's scope they contain no equations, optimization variables, parameters, domains, bounds, or quantitative relations. This is a substantive non-mathematical determination, not an inference from missing extraction. The B evidence remains unreviewed; no independent source audit is claimed.","bindings":[],"revision_requests":[]}},"quarantined_references":[]}});
